/* iScribe offline shell. Generated by Vite at build time.
 * Only same-origin, build-pinned application files are stored here.
 * Model files remain in transformers-cache; audio and transcripts are NEVER
 * cached by the Service Worker.
 */
const BUILD_ID='__ISCRIBE_BUILD_ID__';
const ASSET_PATHS=__ISCRIBE_ASSET_LIST__;
const SHELL_CACHE='iscribe-shell-'+BUILD_ID;
const scope=self.registration.scope;
const shellUrls=ASSET_PATHS.map(path=>new URL(path,scope).href);
const allowedAssets=new Set(shellUrls);
const indexUrl=new URL('index.html',scope).href;

self.addEventListener('install',event=>{
 event.waitUntil((async()=>{
  // A partial precache must not activate; old active worker stays usable.
  const cache=await caches.open(SHELL_CACHE);
  await cache.addAll(shellUrls.map(url=>new Request(url,{cache:'reload'})));
  // Do NOT call skipWaiting: active audio jobs belong to the previous build.
 })());
});
self.addEventListener('activate',event=>{
 event.waitUntil((async()=>{
  const names=await caches.keys();
  await Promise.all(names.filter(name=>name.startsWith('iscribe-shell-')&&name!==SHELL_CACHE).map(name=>caches.delete(name)));
  await self.clients.claim();
 })());
});
self.addEventListener('fetch',event=>{
 const request=event.request;
 if(request.method!=='GET')return;
 const target=new URL(request.url);
 if(target.origin!==self.location.origin)return;
 if(request.mode==='navigate'){
  event.respondWith((async()=>{
   try{
    const response=await fetch(request);
    if(response.ok)return response;
   }catch{/* Offline: use the pinned shell. */}
   const cache=await caches.open(SHELL_CACHE);
   return await cache.match(indexUrl)||Response.error();
  })());
  return;
 }
 // Unknown assets, user audio and API requests are NEVER inserted into this cache.
 if(!allowedAssets.has(target.href)||request.headers.has('Range'))return;
 event.respondWith((async()=>{
  const cache=await caches.open(SHELL_CACHE);
  const hit=await cache.match(request);
  if(hit)return hit;
  return fetch(request);
 })());
});
self.addEventListener('message',event=>{
 if(event.data?.type!=='iscribe:offline-probe'||!event.ports?.[0])return;
 event.waitUntil((async()=>{
  let shellComplete=false,wasmCached=false,missing=ASSET_PATHS.length;
  try{
   const cache=await caches.open(SHELL_CACHE);
   const results=await Promise.all(shellUrls.map(url=>cache.match(url)));
   missing=results.filter(response=>!response?.ok).length;
   shellComplete=missing===0;
   const wasm=ASSET_PATHS.map((path,i)=>({path,response:results[i]}))
    .filter(item=>item.path.endsWith('.wasm.gz.bin'));
   wasmCached=wasm.length>0&&wasm.every(item=>item.response?.ok);
  }catch{/* Report incomplete shell, never invent readiness. */}
  event.ports[0].postMessage({
   type:'iscribe:offline-probe-result',
   buildId:BUILD_ID,shellComplete,wasmCached,missing,assetCount:ASSET_PATHS.length
  });
 })());
});
